// See handler.ts. Deployed with verify_jwt = false (other apps have no SYNAPSE login); the secret
// token in the link is what lets a contact in.
import { createClient } from "npm:@supabase/supabase-js@2.45.0";

const db = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!, { auth: { persistSession: false } });

const deps: Deps = {
  async addContact(token, payload) {
    const { data, error } = await db.rpc("inbound_contact", { p_token: token, p_payload: payload });
    if (error) { console.error("inbound_contact failed", error.message); throw error; }
    return data as Result;
  },
};

Deno.serve((req) => handle(req, deps));

// ---------- handler.ts ----------
// SYNAPSE's API for other apps. For now: incoming contact links. Zapier, Make, a website form or
// a live chat adds or updates a contact by POSTing to the link an Admin made in Settings → API:
//
//   POST https://<project>.supabase.co/functions/v1/api/incoming/<token>
//   POST https://<project>.supabase.co/functions/v1/api/incoming?token=<token>
//
// Body: JSON { "email": "...", "first_name": "...", "tags": ["VIP"], "message": "..." } or a form
// post (email=...&first_name=...). Needs an email or a phone. The database (inbound_contact) does
// the matching, tagging and logging.
//
// -> 201 { ok, contact_id, created: true }   200 { ok, contact_id, created: false }
//    400 not JSON/form   404 unknown or switched-off link   413 over 64 KB   422 no email/phone
//    429 over 120 a minute

export interface Result { ok: boolean; status: number; error?: string; contact_id?: string; created?: boolean }

export interface Deps {
  addContact(token: string, payload: Record<string, unknown>): Promise<Result>;
}

export const MAX_BYTES = 64 * 1024;

const cors = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Client-Info, Apikey",
};
const json = (status: number, body: unknown) =>
  new Response(JSON.stringify(body), { status, headers: { ...cors, "Content-Type": "application/json" } });

/** "incoming" and the token from /api/incoming/<token> or /api/incoming?token=<token>. */
export function route(url: string): { kind: "incoming" | null; token: string | null } {
  const u = new URL(url);
  const parts = u.pathname.split("/").filter(Boolean);
  const at = parts.indexOf("incoming");
  if (at < 0) return { kind: null, token: null };
  const t = (u.searchParams.get("token") ?? parts[at + 1] ?? "").trim();
  return { kind: "incoming", token: /^[a-f0-9]{32,128}$/i.test(t) ? t.toLowerCase() : null };
}

/** The posted fields, from JSON or a form post. Null when it's neither. */
export function readBody(raw: string, contentType: string): Record<string, unknown> | null {
  const type = contentType.toLowerCase();
  if (type.includes("application/x-www-form-urlencoded")) return Object.fromEntries(new URLSearchParams(raw));
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

export async function handle(req: Request, deps: Deps): Promise<Response> {
  if (req.method === "OPTIONS") return new Response(null, { status: 200, headers: cors });
  const { kind, token } = route(req.url);
  if (!kind) return json(404, { error: "Unknown address. Incoming contact links look like /functions/v1/api/incoming/<token>." });
  if (req.method !== "POST") return json(405, { error: "Send a POST request." });
  if (!token) return json(404, { error: "This link is missing its token." });

  const raw = await req.text();
  if (new TextEncoder().encode(raw).length > MAX_BYTES) return json(413, { error: "Too large: send at most 64 KB." });
  const body = readBody(raw, req.headers.get("content-type") ?? "");
  if (!body) return json(400, { error: 'Send JSON like { "email": "jane@example.com", "first_name": "Jane" }, or a form post.' });

  const r = await deps.addContact(token, body).catch(() => null);
  if (!r) return json(500, { error: "Couldn't save the contact. Try again." });
  const { status, ...rest } = r;
  return json(status || (r.ok ? 200 : 400), rest);
}
